{
  "representation_type": "integral_representation_difference",
  "latent_object": {
    "id": "L1",
    "type": "parametric_kernel",
    "expression": "sin(y*t)/(2*sinh(t/2))",
    "parameters": ["y"],
    "domain": "t>0"
  },
  "member_maps": [
    {
      "source_node_id": "G0001",
      "role": "target_expression"
    }
  ],
  "operators": [
    {
      "id": "O1",
      "name": "weighted_sine_transform",
      "input": "L1",
      "output": "A1",
      "definition": "A1 = ∫_{0}^{∞} sin(y*t)/(2*sinh(t/2)) dt"
    },
    {
      "id": "O2",
      "name": "tanh_scaling",
      "input": "y",
      "output": "A2",
      "definition": "A2 = (π/2)*tanh(π*y)"
    },
    {
      "id": "O3",
      "name": "subtraction",
      "input": ["A1", "A2"],
      "output": "H1",
      "definition": "H1 = A1 - A2"
    }
  ],
  "reconstruction_rule": "G0001 is reconstructed as H1 = A1 - A2, where A1 is the weighted sine transform of the latent kernel L1 and A2 is the scaled hyperbolic tangent term.",
  "required_assumptions": [
    "y is real",
    "the weighted sine transform A1 converges for all real y",
    "digamma uses the principal branch with Re(1/2 + i*y) = 1/2 > 0"
  ],
  "proof_obligations": [
    "Show A1 equals Im(polygamma(0, 1/2 + i*y)) via the standard digamma integral representation",
    "Show A2 matches the term (π/2)*tanh(π*y) exactly",
    "Show the reconstruction is well-defined for all real y"
  ]
}
